function validate([nums, locked]) {
  if (nums.length < 1 || nums.length > 100000) return 'nums needs 1 to 100000 values.';
  if (locked.length !== nums.length) return 'locked must be as long as nums.';
  if (nums.some(v => v !== 1 && v !== 2 && v !== 3)) return 'Each value in nums is 1, 2 or 3.';
  if (locked.some(v => v !== 0 && v !== 1)) return 'Each value in locked is 0 or 1.';
  return null;
}

