function minUnlockedIndices(nums, locked) {
  const n = nums.length;
  let lastOne = -1;
  let lastTwo = -1;
  for (let i = 0; i < n; i++) {
    if (nums[i] === 1) {
      lastOne = i;
    } else if (nums[i] === 2) {
      lastTwo = i;
    }
  }
  let seenTwo = false;
  let seenThree = false;
  let unlocks = 0;
  for (let i = 0; i < n; i++) {
    if (nums[i] === 2) {
      seenTwo = true;
    } else if (nums[i] === 3) {
      seenThree = true;
    }
    // A 3 and a 1 differ by 2, so a 3 can never get past a 1.
    if (seenThree && i < lastOne) {
      return -1;
    }
    // Some value must cross the boundary between i and i + 1.
    const mustSwap = (seenTwo && i < lastOne) || (seenThree && i < lastTwo);
    if (mustSwap && locked[i] === 1) {
      unlocks++;
    }
  }
  return unlocks;
}

