function minUnlockedIndices(nums, locked) {
  const n = nums.length;
  const target = [...nums].sort((a, b) => a - b).join('');
  // Breadth-first search over every arrangement reachable with the swaps that `open` allows.
  const sortable = open => {
    const start = nums.join('');
    const seen = new Set([start]);
    const queue = [start];
    for (let q = 0; q < queue.length; q++) {
      const s = queue[q];
      if (s === target) return true;
      for (let i = 0; i + 1 < n; i++) {
        if (!open[i] || Number(s[i]) - Number(s[i + 1]) !== 1) continue;
        const t = s.slice(0, i) + s[i + 1] + s[i] + s.slice(i + 2);
        if (!seen.has(t)) { seen.add(t); queue.push(t); }
      }
    }
    return false;
  };
  if (!sortable(nums.map(() => true))) return -1;
  // Try every set of locked indices to unlock and keep the smallest set that makes nums sortable.
  const closed = [];
  for (let i = 0; i < n; i++) if (locked[i] === 1) closed.push(i);
  let best = closed.length;
  for (let mask = 0; mask < 1 << closed.length; mask++) {
    const chosen = closed.filter((_, b) => (mask >> b) & 1);
    if (chosen.length >= best) continue;
    const open = locked.map(v => v === 0);
    for (const i of chosen) open[i] = true;
    if (sortable(open)) best = chosen.length;
  }
  return best;
}

