function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const n = size === 'large' ? 2000 : 1 + pick(8);
  const kinds = [[1, 2], [2, 3], [1, 2, 3], [1, 2, 3]][pick(4)];
  let nums = Array.from({ length: n }, () => kinds[pick(kinds.length)]).sort((a, b) => a - b);
  // Scramble the sorted array with reversed allowed swaps: 1s and 3s never cross, so it stays sortable.
  const scrambles = size === 'large' ? 40000 : n + pick(3 * n);
  for (let t = 0; t < scrambles && n > 1; t++) {
    const i = pick(n - 1);
    if (nums[i + 1] - nums[i] === 1) [nums[i], nums[i + 1]] = [nums[i + 1], nums[i]];
  }
  // Now and then use a fully random array instead, which usually puts a 3 before a 1.
  if (rand() < 0.2) nums = Array.from({ length: n }, () => 1 + pick(3));
  const density = [0.2, 0.5, 0.8, 1][pick(4)];
  return [nums, Array.from({ length: n }, () => (rand() < density ? 1 : 0))];
}
